"use client";

import { typography } from "../lib/typography.shared";
import { memo, useId, useRef, type ReactNode } from "react";
import { X } from "lucide-react";
import { LazyMotion, domAnimation, useAnimationControls, useReducedMotion } from "motion/react";
import * as m from "motion/react-m";
import { Button } from "./button";
import { Card } from "./card";

interface BottomSheetProps {
  triggerLabel?: string;
  title?: string;
  description?: string;
  children?: ReactNode;
  className?: string;
}

export const BottomSheet = memo(function BottomSheet({
  triggerLabel = "Open bottom sheet",
  title = "Make yourself at home",
  description = "A little space for your next action. Press Escape or close to return.",
  children,
  className = "",
}: BottomSheetProps = {}) {
  const dialog = useRef<HTMLDialogElement>(null);
  const id = useId();
  const animation = useAnimationControls();
  const textAnimation = useAnimationControls();
  const reducedMotion = useReducedMotion();
  const closing = useRef(false);

  const textVariants = {
    hidden: { opacity: 0, y: reducedMotion ? 0 : 12, transition: { duration: reducedMotion ? 0 : 0.12 } },
    visible: { opacity: 1, y: 0 },
  };

  const openSheet = async () => {
    const sheet = dialog.current;
    if (!sheet || sheet.open) return;
    textAnimation.set("hidden");
    animation.set({ y: 0, opacity: 0, width: "100%", height: "auto" });
    // Motion renders on the next frame; measure the natural size immediately on reopen.
    sheet.style.width = "100%";
    sheet.style.height = "auto";
    sheet.showModal();
    const { width, height } = sheet.getBoundingClientRect();
    sheet.style.overflow = "hidden";
    animation.set({
      width: reducedMotion ? width : Math.min(144, width),
      height: reducedMotion ? height : Math.min(64, height),
      y: reducedMotion ? 0 : "100%",
      opacity: 0,
    });
    await animation.start({
      y: 0,
      opacity: 1,
      transition: reducedMotion ? { duration: 0 } : { type: "spring", stiffness: 280, damping: 30 },
    });
    if (!sheet.open || closing.current) return;
    await animation.start({
      width,
      height,
      transition: { duration: reducedMotion ? 0 : 0.35, ease: [0.22, 1, 0.36, 1] },
    });
    if (!sheet.open || closing.current) return;
    animation.set({ width: "100%", height: "auto" });
    sheet.style.overflow = "";
    void textAnimation.start("visible");
  };

  const closeSheet = async () => {
    const sheet = dialog.current;
    if (!sheet?.open || closing.current) return;
    closing.current = true;
    animation.stop();
    textAnimation.stop();
    sheet.style.overflow = "hidden";
    const { width, height } = sheet.getBoundingClientRect();
    animation.set({ width, height });
    await textAnimation.start("hidden");
    await animation.start({
      width: reducedMotion ? width : Math.min(144, width),
      height: reducedMotion ? height : Math.min(64, height),
      transition: { duration: reducedMotion ? 0 : 0.3, ease: [0.22, 1, 0.36, 1] },
    });
    await animation.start({
      y: reducedMotion ? 0 : "calc(100% + 16px)",
      opacity: 0,
      transition: { duration: reducedMotion ? 0 : 0.2, ease: "easeIn" },
    });
    sheet.close();
    sheet.style.overflow = "";
    closing.current = false;
  };

  return (
    <LazyMotion features={domAnimation} strict>
      <div className={className}>
        <Button
          type="button"
          aria-haspopup="dialog"
          onClick={() => void openSheet()}
        >
          {triggerLabel}
        </Button>
        <m.dialog
          ref={node => {
            dialog.current = node;
            node?.setAttribute("closedby", "any");
          }}
          initial={{ y: "100%", opacity: 0 }}
          animate={animation}
          onCancel={event => {
            event.preventDefault();
            void closeSheet();
          }}
          aria-labelledby={`${id}-title`}
          aria-describedby={`${id}-description`}
          className="fixed inset-x-0 bottom-4 top-auto mx-auto my-0 max-h-[85dvh] w-full max-w-none overflow-y-auto border border-border bg-card p-0 text-card-foreground shadow-xl backdrop:bg-black/60 sm:mx-auto sm:max-w-xl"
        >
          <Card title="" description="" className="relative max-w-none! border-0!">
            <m.div
              className="absolute right-3 top-3 z-10"
              initial="hidden"
              animate={textAnimation}
              variants={{ hidden: { opacity: 0, visibility: "hidden" }, visible: { opacity: 1, visibility: "visible" } }}
              transition={{ duration: reducedMotion ? 0 : 0.15 }}
            >
              <Button
                type="button"
                variant="ghost"
                aria-label="Close bottom sheet"
                onClick={() => void closeSheet()}
                className="size-11 p-0!"
              >
                <X aria-hidden="true" size={24} />
              </Button>
            </m.div>
            <div
              aria-hidden="true"
              className="mx-auto mb-6 h-1 w-10 bg-muted-foreground/40"
            />
            <m.div
              initial="hidden"
              animate={textAnimation}
              variants={{ hidden: {}, visible: { transition: { staggerChildren: reducedMotion ? 0 : 0.18 } } }}
            >
              <m.div className="flex items-start justify-between gap-4 pr-12" variants={textVariants} transition={{ duration: reducedMotion ? 0 : 0.45, ease: "easeOut" }}>
                <h2 id={`${id}-title`} className={typography.sectionTitle}>
                  {title}
                </h2>

              </m.div>
              <m.p
                variants={textVariants}
                transition={{ duration: reducedMotion ? 0 : 0.45, ease: "easeOut" }}
                id={`${id}-description`}
                className={`mt-3 ${typography.body}`}
              >
                {description}
              </m.p>
              {children && <m.div className="mt-6" variants={textVariants} transition={{ duration: reducedMotion ? 0 : 0.45, ease: "easeOut" }}>{children}</m.div>}
            </m.div>
          </Card>
        </m.dialog>
      </div>
    </LazyMotion>
  );
});

import { memo, type ComponentProps } from "react";

type ButtonProps = {
  variant?: "primary" | "secondary" | "ghost" | "destructive" | "outline";
} & (ComponentProps<"button"> & { href?: never } | ComponentProps<"a"> & { href: string });

export const Button = memo(function Button({
  children = "Get started",
  variant = "primary",
  className = "",
  ...props
}: ButtonProps = {}) {
  const styles = {
    primary: "bg-emerald-400 text-neutral-950 hover:bg-emerald-300",
    secondary: "bg-neutral-800 text-white hover:bg-neutral-700",
    ghost: "bg-transparent text-foreground hover:bg-muted",
    destructive: "bg-destructive text-destructive-foreground hover:bg-destructive/90",
    outline: "border border-border text-white hover:bg-neutral-800",
  };
  const classes = `inline-flex min-h-11 items-center justify-center gap-2 px-5 py-2 text-sm font-semibold transition-colors focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-emerald-400 disabled:pointer-events-none disabled:opacity-50 ${styles[variant] ?? styles.primary} ${className}`;

  if (props.href !== undefined) {
    return <a className={classes} {...props}>{children}</a>;
  }

  return (
    <button
      type="button"
      className={classes}
      {...props}
    >
      {children}
    </button>
  );
});

import { typography } from "../lib/typography.shared";
import type { ComponentProps, ReactNode } from "react";

interface CardProps extends Omit<ComponentProps<"article">, "title"> {
  title?: string;
  description?: string;
  footer?: ReactNode;
}

export function Card({ title = "Room for your next idea", description = "A simple starting point for something great. Make it yours.", children, footer, className = "", ...props }: CardProps = {}) {
  return <article className={`w-full max-w-sm border border-border bg-card p-6 text-base leading-7 text-card-foreground shadow-sm ${className}`} {...props}>
    {title && <h3 className={typography.sectionTitle}>{title}</h3>}
    {description && <p className={`mt-2 ${typography.body}`}>{description}</p>}
    {children && <div className={title || description || footer ? "mt-5" : "h-full min-h-0"}>{children}</div>}
    {footer && <footer className="mt-5 border-t border-border pt-4">{footer}</footer>}
  </article>;
}

/** Shared text hierarchy for documentation and component content. */
export const typography = {
  pageTitle: "text-4xl font-semibold tracking-tight text-foreground sm:text-5xl",
  sectionTitle: "text-2xl font-semibold tracking-tight text-foreground",
  subsectionTitle: "text-xl font-semibold tracking-tight text-foreground",
  body: "text-base leading-7 text-muted-foreground",
  label: "text-sm font-medium",
  caption: "text-sm leading-6 text-muted-foreground",
} as const;
